<?php require "vendor/autoload.php"; $app = require_once "bootstrap/app.php"; $kernel = $app->make(Illuminate\Contracts\Console\Kernel::class); $kernel->bootstrap(); $ps = App\Models\Payment::whereNotNull("repayment_transaction_id")->get(); foreach($ps as $p) { if (!App\Models\RepaymentTransaction::find($p->repayment_transaction_id)) { echo "Clearing Orphaned TX ID ".$p->repayment_transaction_id." from payment row ".$p->id."\n"; $p->repayment_transaction_id = null; $p->save(); } } echo "Sync complete.\n";
